condition.script:

import com.liferay.portal.kernel.service.RoleLocalServiceUtil;
import com.liferay.portal.kernel.service.UserGroupRoleLocalServiceUtil;
import com.liferay.portal.kernel.util.GetterUtil;
import com.liferay.portal.kernel.workflow.WorkflowConstants;

long companyId = GetterUtil.getLong((String)workflowContext.get(WorkflowConstants.CONTEXT_COMPANY_ID));
long userId = GetterUtil.getLong((String)workflowContext.get(WorkflowConstants.CONTEXT_USER_ID));
long groupId = GetterUtil.getLong((String)workflowContext.get(WorkflowConstants.CONTEXT_GROUP_ID));

boolean autoApprove = false;

String[] regularRoles = [
	"Administrator",
	"Quản trị nội dung",
	"News Briefs Editor"
] as String[];

for (String roleName : regularRoles) {
	try {
		if (RoleLocalServiceUtil.hasUserRole(userId, companyId, roleName, false)) {
			autoApprove = true;
			break;
		}
	}
	catch (Exception e) {
	}
}

if (!autoApprove && groupId > 0) {
	try {
		if (UserGroupRoleLocalServiceUtil.hasUserGroupRole(userId, groupId, "Site Administrator", false)) {
			autoApprove = true;
		}
	}
	catch (Exception e) {
	}
}

returnValue = autoApprove ? "approve" : "review";
